import { Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { DestroyRef } from '@angular/core';
import { interval } from 'rxjs';

// LEAKS: never unsubscribed, keeps firing after destroy
// ngOnInit() { interval(1000).subscribe(v => this.tick = v); }

@Component({ selector: 'app-ticker', standalone: true, template: `{{ tick }}` })
export class TickerComponent {
  tick = 0;
  private destroyRef = inject(DestroyRef);

  constructor() {
    interval(1000)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(v => (this.tick = v)); // auto-unsubscribes on destroy
  }
}

import { Component } from '@angular/core';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { debounceTime, distinctUntilChanged, switchMap, filter } from 'rxjs/operators';

@Component({
  selector: 'app-search',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `<input [formControl]="query" />`,
})
export class SearchComponent {
  query = new FormControl('');

  results$ = this.query.valueChanges.pipe(
    debounceTime(300),                 // wait for typing to pause
    distinctUntilChanged(),            // skip duplicate terms
    filter((q): q is string => !!q && q.length > 1),
    switchMap(q => this.http.get(`/api/search?q=${q}`)) // cancels stale request
  );

  constructor(private http: HttpClient) {}
}

import { Component, signal, computed, effect } from '@angular/core';

@Component({
  selector: 'app-cart',
  standalone: true,
  template: `
    <button (click)="add()">Add</button>
    <p>Items: {{ count() }} - Total: {{ total() }}</p>
  `,
})
export class CartComponent {
  count = signal(0);
  price = signal(10);

  // computed: memoized, recomputes only when count or price change
  total = computed(() => this.count() * this.price());

  constructor() {
    // effect: side effect that re-runs whenever read signals change
    effect(() => console.log('Total is now', this.total()));
  }

  add() {
    this.count.update(c => c + 1);
  }
}

