import { Directive, Input, TemplateRef, ViewContainerRef } from '@angular/core';

@Directive({ selector: '[appUnless]', standalone: true })
export class UnlessDirective {
  private hasView = false;

  constructor(
    private templateRef: TemplateRef<unknown>,
    private viewContainer: ViewContainerRef
  ) {}

  @Input() set appUnless(condition: boolean) {
    if (!condition && !this.hasView) {
      this.viewContainer.createEmbeddedView(this.templateRef);
      this.hasView = true;
    } else if (condition && this.hasView) {
      this.viewContainer.clear();
      this.hasView = false;
    }
  }
}

// Usage: <p *appUnless="isLoggedIn">Please log in.</p>

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'filterBy', standalone: true, pure: true })
export class FilterByPipe implements PipeTransform {
  transform<T>(items: T[], term: string, key: keyof T): T[] {
    if (!items || !term) return items;
    const lower = term.toLowerCase();
    return items.filter(i => String(i[key]).toLowerCase().includes(lower));
  }
}

// Pure: updates only when 'items' reference or 'term' changes.
// Mutating items via push() will NOT refresh -> reassign: this.items = [...this.items, newItem];
// Use pure:false only if you truly must react to in-place mutations (perf cost).

import { Component } from '@angular/core';
import { NgIf } from '@angular/common';
import { FormBuilder, ReactiveFormsModule, AbstractControl, ValidationErrors, Validators } from '@angular/forms';

function passwordsMatch(group: AbstractControl): ValidationErrors | null {
  const pw = group.get('password')?.value;
  const confirm = group.get('confirm')?.value;
  return pw === confirm ? null : { mismatch: true };
}

@Component({
  selector: 'app-signup',
  standalone: true,
  imports: [ReactiveFormsModule, NgIf],
  template: `
    <form [formGroup]="form">
      <input formControlName="password" type="password" />
      <input formControlName="confirm" type="password" />
      <p *ngIf="form.errors?.['mismatch']">Passwords must match</p>
    </form>
  `,
})
export class SignupComponent {
  form = this.fb.group(
    {
      password: ['', [Validators.required, Validators.minLength(8)]],
      confirm: ['', Validators.required],
    },
    { validators: passwordsMatch }
  );

  constructor(private fb: FormBuilder) {}
}

import { CanActivateFn, Router, Routes } from '@angular/router';
import { inject } from '@angular/core';
import { AuthService } from './auth.service';

export const authGuard: CanActivateFn = (route, state) => {
  const auth = inject(AuthService);
  const router = inject(Router);
  if (auth.isLoggedIn()) return true;
  return router.createUrlTree(['/login'], { queryParams: { redirect: state.url } });
};

export const routes: Routes = [
  {
    path: 'dashboard',
    canActivate: [authGuard],
    loadComponent: () =>
      import('./dashboard/dashboard.component').then(m => m.DashboardComponent),
  },
  {
    path: 'admin',
    canMatch: [authGuard], // also avoids loading the chunk when unauthorized
    loadChildren: () => import('./admin/admin.routes').then(m => m.ADMIN_ROUTES),
  },
];

import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-counter',
  standalone: true,
  template: `
    <button (click)="dec()">-</button>
    {{ value }}
    <button (click)="inc()">+</button>
  `,
})
export class CounterComponent {
  @Input() value = 0;
  @Output() valueChange = new EventEmitter<number>(); // name MUST be value + 'Change'

  inc() { this.valueChange.emit(this.value + 1); }
  dec() { this.valueChange.emit(this.value - 1); }
}

